import json, ssl, socket, urllib.request, urllib.parse, sys
from concurrent.futures import ThreadPoolExecutor
EXPECTED={"185.199.108.153","185.199.109.153","185.199.110.153","185.199.111.153"}
def dns(name, kind):
    url="https://dns.google/resolve?"+urllib.parse.urlencode({"name":name,"type":kind})
    with urllib.request.urlopen(url, timeout=12) as response:
        data=json.load(response)
    if data.get("Status") != 0: raise ValueError("DNS resolver status "+str(data.get("Status")))
    return sorted({a["data"].rstrip(".").lower() for a in data.get("Answer",[]) if a.get("type")==kind})
def https(host):
    with socket.create_connection((host,443), timeout=12) as connection:
        with ssl.create_default_context().wrap_socket(connection,server_hostname=host) as tls:
            cert=tls.getpeercert()
    with urllib.request.urlopen("https://"+host+"/",timeout=12) as response:
        return {"certificate_trusted":True,"expires":cert.get("notAfter"),"http_status":response.status,"final_url":response.url}
def check(name,fn):
    try: return name,{"state":"OBSERVED","value":fn()}
    except Exception as error: return name,{"state":"UNKNOWN","error":type(error).__name__+": "+str(error)}
jobs=[("apex_a",lambda:dns("infofaqs.com",1)),("www_cname",lambda:dns("www.infofaqs.com",5)),("apex_https",lambda:https("infofaqs.com")),("www_https",lambda:https("www.infofaqs.com"))]
with ThreadPoolExecutor(max_workers=4) as pool:
    results=dict(pool.map(lambda job:check(*job),jobs))
known=all(v["state"]=="OBSERVED" for v in results.values())
matched=known and set(results["apex_a"]["value"])==EXPECTED and results["www_cname"]["value"]==["eternalimit.github.io"] and all(results[k]["value"]["http_status"]==200 and results[k]["value"]["final_url"]=="https://infofaqs.com/" for k in ("apex_https","www_https"))
print(json.dumps({"status":"PASS" if matched else "HOLD","scope":"Public resolver IPv4/CNAME and HTTPS homepage checks only; not a DNS repair or full release approval","results":results},indent=2,sort_keys=True))
sys.exit(0 if matched else 2)
